/* @lc app=leetcode id=1761 lang=kotlin */
class Solution { fun minTrioDegree(n: Int, edges: Array<IntArray>): Int = BooleanArray((n + 1) * (n + 1)).let { g -> IntArray(n + 1).let { deg -> edges.forEach { e -> g.apply { this[e[0] * (n + 1) + e[1]] = true }.apply { this[e[1] * (n + 1) + e[0]] = true }.run { deg.apply { this[e[0]]++ }.apply { this[e[1]]++ } } }.run { (1..n).fold(Int.MAX_VALUE) { minD, u -> (u + 1..n).fold(minD) { minD2, v -> if (g[u * (n + 1) + v]) (v + 1..n).fold(minD2) { minD3, w -> if (g[u * (n + 1) + w] && g[v * (n + 1) + w]) minOf(minD3, deg[u] + deg[v] + deg[w] - 6) else minD3 } else minD2 } }.let { if (it == Int.MAX_VALUE) -1 else it } } } }}